struct Service {int uploads=0;void setEnabled(bool){}void setApiKey(QString){}void setApiUrl(QString){}void setStationId(int){}void setReplaceDuplicates(bool){}void uploadAdif(QString,QByteArray,quint32){++uploads;}};
class DecodiumBridge:public QObject {public:
 struct ExternalAdifUploadPending{QString dxCall,target;QStringList pendingBackends,sentBackends,failedBackends,skippedTargets,immediateTargets;};
 QHash<quint32,ExternalAdifUploadPending> m_externalAdifUploads;QHash<QString,QVariant> settings;bool m_qrzLogbookEnabled=false,m_qrzLogbookReplaceDuplicates=false,m_cloudlogEnabled=false;QString m_qrzLogbookApiKey,m_cloudlogUrl,m_cloudlogApiKey;Service q,c,*m_qrzLogbook=&q,*m_cloudlog=&c;QStringList events;
 QVariant getSetting(QString k,QVariant d)const{return settings.value(k,d);}bool udpTrafficEnabled(QString p,QString)const{return settings.value(p+"SendQso",true).toBool();}bool udpSendRawAdifDatagram(QString,QString,quint16,QString,QByteArray){return settings.value("rawOk",true).toBool();}void udpSendN1mmLoggedQso(QString,QByteArray){events<<"n1mm";}void tcpSendLoggedAdifQso(QString,QByteArray){events<<"tcp";}
 void externalAdifUploadStatus(quint32 id,QString state,QString detail){events<<QString("status:%1:%2:%3").arg(id).arg(state,detail);}void statusMessage(QString s){events<<"ok:"+s;}void errorMessage(QString s){events<<"error:"+s;}
 QVariantMap uploadExternalAdif(QString const&,QString const&,QString const&);QVariantMap uploadExternalAdifForOutbox(quint32,QString const&,QString const&,QString const&);QVariantMap uploadExternalAdifInternal(quint32,QString const&,QString const&,QString const&);void noteExternalAdifUploadBackend(quint32,QString const&,QString const&,bool,QString const&);void finishExternalAdifUploadIfReady(quint32);
};
