static void printResult(QString label,QVariantMap const&r){printf("%s|ok=%d|target=%s|state=%s|attempt=%s|skip=%s|pending=%s\n",label.toUtf8().constData(),r.value("ok").toBool(),r.value("target").toString().toUtf8().constData(),r.value("state").toString().toUtf8().constData(),r.value("attempted").toStringList().join(';').toUtf8().constData(),r.value("skipped").toStringList().join(';').toUtf8().constData(),r.value("pending").toStringList().join(';').toUtf8().constData());}
int main(int argc,char**argv){QCoreApplication app(argc,argv);for(QString target:QStringList{"UDP","N1MM","TCP","QRZ","CLOUDLOG","ALL","unknown"}){DecodiumBridge b;b.settings["UDPSecondaryEnabled"]=false;b.settings["BroadcastToN1MM"]=true;b.settings["ADIFTcpEnabled"]=true;b.m_qrzLogbookEnabled=true;b.m_cloudlogEnabled=true;auto r=b.uploadExternalAdifForOutbox(42," k1abc "," <CALL:5>K1ABC ",target);printResult(target,r);if(!r.value("pending").toStringList().isEmpty()){b.noteExternalAdifUploadBackend(42,"QRZ Logbook","K1ABC",true,"done");b.noteExternalAdifUploadBackend(42,"Cloudlog","K1ABC",false,"failed");}QCoreApplication::processEvents();printf("services=%d,%d pending=%d events=%s\n",b.q.uploads,b.c.uploads,int(b.m_externalAdifUploads.size()),b.events.join('|').toUtf8().constData());}DecodiumBridge b;printResult("missing",b.uploadExternalAdif("","", "UDP"));b.settings["rawOk"]=false;b.settings["UDPSecondaryEnabled"]=false;printResult("raw-failure",b.uploadExternalAdif("K1ABC","<CALL:5>K1ABC","UDP"));}
